insert into public.demo_items (entity_id, kind, name, price, price_text, currency, image_url, description, source_url, extra, sort_at) select id, 'product', 'Absorbent Paper Points', null, null, null, 'https://asiastom.uz/thumb/2/qEhl7g0fuWIR1bYNnajChQ/1200r/d/absorbet_paper_points_bez_fona_809985.png', 'Absorbent Paper Points — бумажные абсорбирующие штифты Это одноразовые, высокоабсорбирующие бумажные конусы, используемые стоматологами в эндодонтическом лечении для тщательной просушки корневого канала после его очистки и формирования, перед финальным пломбированием, чтобы удалить остатки влаги и медикаментов, обеспечивая сухое пространство для герметичного заполнения. Преимущества: Эффективное высушивание корневых каналов Простота и удобство в использовании Совместимость с эндодонтическими материалами Показания: Высушивание корневых каналов перед пломбированием Форма выпуска : Наборы…', 'https://asiastom.uz/absorbent-paper-points', '{"storage_path": "demo/asia-stom-plus/1.png"}'::jsonb, 0 from public.demo_entities where slug = 'asia-stom-plus' and not exists (select 1 from public.demo_items x where x.entity_id = demo_entities.id and x.source_url = 'https://asiastom.uz/absorbent-paper-points' and x.name = 'Absorbent Paper Points');
insert into public.demo_items (entity_id, kind, name, price, price_text, currency, image_url, description, source_url, extra, sort_at) select id, 'product', 'Adseal', null, null, null, 'https://asiastom.uz/thumb/2/wsL4Ek36oHKfZ1-U1yGn1w/1200r/d/adseal_bez_fona.png', 'Adseal - двухкомпонентный пломбировочный эндодонтический силер на основе эпоксидной смолы в двойном шприце, состоящий из паст основы и катализатора, для окончательного пломбирования корневых каналов постоянных зубов в комбинации с гуттаперчевыми штифтами. Эндодонтический силер ADSEAL созданный для постоянной и абсолютно герметичной обтурации корневых каналов. Поставляемый в удобном двойном шприце (13.5 г), он обеспечивает простоту в работе и предсказуемо превосходный результат. Преимущества Высокая биосовместимость — материал на основе эпоксидной смолы с подтверждённой переносимостью тканями…', 'https://asiastom.uz/adseal', '{"storage_path": "demo/asia-stom-plus/2.png"}'::jsonb, 1 from public.demo_entities where slug = 'asia-stom-plus' and not exists (select 1 from public.demo_items x where x.entity_id = demo_entities.id and x.source_url = 'https://asiastom.uz/adseal' and x.name = 'Adseal');
insert into public.demo_items (entity_id, kind, name, price, price_text, currency, image_url, description, source_url, extra, sort_at) select id, 'product', 'Biner LC', null, null, null, 'https://asiastom.uz/thumb/2/3hlMwgjfESCn-0p8GJ31Xw/1200r/d/biner_kvadr_horoshee_kach.jpg', 'Biner LC — светоотверждаемый фторвыделяющий лайнерный материал. Он предназначен для защиты пульпы и твердых тканей зуба при выполнении реставраций композитными материалами. Обеспечивает химическую и микромеханическую адгезию к дентину, высокую биосовместимость и стабильное выделение ионов фтора и кальция, способствующих реминерализации и снижению риска кариозных поражений. Материал обладает выраженной рентгеноконтрастностью, не растворим в слюне и воде, легко наносится и поставляется с канюлями для точного введения в полость зуба. Преимущества: • Светоотверждаемый фторвыделяющий лайнер •…', 'https://asiastom.uz/biner-lc', '{"storage_path": "demo/asia-stom-plus/3.jpg"}'::jsonb, 2 from public.demo_entities where slug = 'asia-stom-plus' and not exists (select 1 from public.demo_items x where x.entity_id = demo_entities.id and x.source_url = 'https://asiastom.uz/biner-lc' and x.name = 'Biner LC');
