insert into public.demo_items (entity_id, kind, name, price, price_text, currency, image_url, description, source_url, extra, sort_at) select id, 'product', 'Endofill PD', null, null, null, 'https://asiastom.uz/thumb/2/7ZHiqVw55EEb-Xuf9p4VQA/1200r/d/endofil.jpg', 'Endofill – рентгеноконтрастный материал для постоянной обтурации корневых каналов. Препарат обладает высокой биотолерантностью к тканям и оказывает противовоспалительное, антисептическое и бактерицидное действие. До затвердевания паста проникает в тончайшие ответвления основного канала и сохраняет терапевтический эффект в течение лечения и до окончательного отверждения. Постоянная пломба не дает усадки и не резорбируется. Преимущества : Высокая биотолерантность к тканям Противовоспалительное и антисептическое действие Рентгеноконтрастность для контроля пломбирования Оптимальное время…', 'https://asiastom.uz/endofill-pd', '{"storage_path": "demo/asia-stom-plus/6.jpg"}'::jsonb, 5 from public.demo_entities where slug = 'asia-stom-plus' and not exists (select 1 from public.demo_items x where x.entity_id = demo_entities.id and x.source_url = 'https://asiastom.uz/endofill-pd' and x.name = 'Endofill PD');
