insert into public.demo_items (entity_id, kind, name, price, price_text, currency, image_url, description, source_url, extra, sort_at) select id, 'product', 'I-Oil', null, null, null, 'https://asiastom.uz/thumb/2/8nKS3u4ghKlj2AfD1F1nSA/1200r/d/photo_2025-05-10_23-39-29.jpg', 'i -Oil — универсальное масло-спрей для смазки всех типов стоматологических наконечников. Он обеспечивает надёжное обслуживание внутренних механизмов и пневмоприводов, снижает износ и продлевает срок службы инструментов. Удобный спрей-формат позволяет точно дозировать материал, поддерживая оптимальную работоспособность оборудования и экономичный расход. Преимущества: • Подходит для всех видов стоматологических наконечников • Снижает износ и продлевает срок службы инструментов • Удобный спрей-формат для точного и экономичного нанесения • Высокая совместимость с материалами наконечников •…', 'https://asiastom.uz/i-oil', '{"storage_path": "demo/asia-stom-plus/17.jpg"}'::jsonb, 16 from public.demo_entities where slug = 'asia-stom-plus' and not exists (select 1 from public.demo_items x where x.entity_id = demo_entities.id and x.source_url = 'https://asiastom.uz/i-oil' and x.name = 'I-Oil');
