insert into public.demo_items (entity_id, kind, name, price, price_text, currency, image_url, description, source_url, extra, sort_at) select id, 'product', 'Алмазный зуботехнический диск для керамики, пластмассы и гипса.', 39000, '39 000 сўм', 'UZS', 'https://dentashop.uz/wp-content/uploads/2020/08/photo_2020-08-18_15-15-56.jpg', 'Круг алмазный Косой Акрил для сепарации и контуровки керамики, твердых пластмасс, гипса. Идеальный обзор, охлаждение поверхности и удаление продуктов обработки.', 'https://dentashop.uz/product/%d0%b4%d0%b8%d1%81%d0%ba-%d0%be%d1%82%d1%80%d0%b5%d0%b7%d0%bd%d0%be%d0%b9-%d0%b0%d0%bb%d0%bc%d0%b0%d0%b7%d0%bd%d1%8b%d0%b9-%d0%b4%d0%bb%d1%8f-%d0%ba%d0%b5%d1%80%d0%b0%d0%bc%d0%b8%d0%ba%d0%b8-%d0%bf/', '{"storage_path": "demo/dentashop/p02-диск-отрезной-алмазный-для-керамики-п.jpg"}'::jsonb, 1 from public.demo_entities where slug = 'dentashop' and not exists (select 1 from public.demo_items x where x.entity_id = demo_entities.id and x.source_url = 'https://dentashop.uz/product/%d0%b4%d0%b8%d1%81%d0%ba-%d0%be%d1%82%d1%80%d0%b5%d0%b7%d0%bd%d0%be%d0%b9-%d0%b0%d0%bb%d0%bc%d0%b0%d0%b7%d0%bd%d1%8b%d0%b9-%d0%b4%d0%bb%d1%8f-%d0%ba%d0%b5%d1%80%d0%b0%d0%bc%d0%b8%d0%ba%d0%b8-%d0%bf/' and x.name = 'Алмазный зуботехнический диск для керамики, пластмассы и гипса.');
