insert into public.demo_items (entity_id, kind, name, price, price_text, currency, image_url, description, source_url, extra, sort_at) select id, 'product', 'Эндобоксы автоклавируемые.', 260000, '260 000 сўм', 'UZS', 'https://dentashop.uz/wp-content/uploads/2020/08/endoboks_v044_72_otv_d_endoinstrum_105_45_50.jpg', 'Контейнер для дезинфекции с 60 отверстиями Материал: алюминий Цвет: фиолетовый, синий, красный, белый Функция: дезинфекция скоростного бура', 'https://dentashop.uz/product/%d1%8d%d0%bd%d0%b4%d0%be%d0%b1%d0%be%d0%ba%d1%81%d1%8b-%d0%b0%d0%b2%d1%82%d0%be%d0%ba%d0%bb%d0%b0%d0%b2%d0%b8%d1%80%d1%83%d0%b5%d0%bc%d1%8b%d0%b9/', '{"storage_path": "demo/dentashop/p06-эндобоксы-автоклавируемый.jpg"}'::jsonb, 5 from public.demo_entities where slug = 'dentashop' and not exists (select 1 from public.demo_items x where x.entity_id = demo_entities.id and x.source_url = 'https://dentashop.uz/product/%d1%8d%d0%bd%d0%b4%d0%be%d0%b1%d0%be%d0%ba%d1%81%d1%8b-%d0%b0%d0%b2%d1%82%d0%be%d0%ba%d0%bb%d0%b0%d0%b2%d0%b8%d1%80%d1%83%d0%b5%d0%bc%d1%8b%d0%b9/' and x.name = 'Эндобоксы автоклавируемые.');
insert into public.demo_items (entity_id, kind, name, price, price_text, currency, image_url, description, source_url, extra, sort_at) select id, 'product', 'Дистиллятор для воды.', 1300000, '1 300 000 сўм', 'UZS', 'https://dentashop.uz/wp-content/uploads/2020/08/unnamed-2.jpg', 'Дистиллятор для воды. Экономичный, миниатюрный дистиллятор эконом-класса. Производительность 1 л/ч. Идеально подходит для подготовки воды для питания лабораторных и медицинских стерилизаторов и автоклавов. Мощность нагрева 750 Вт. Защита от перегрева, отключение при 160°С. Объем 4л. Внутренний бак изготовлен из нержавеющей стали.', 'https://dentashop.uz/product/%d0%b4%d0%b8%d1%81%d1%82%d0%b8%d0%bb%d0%bb%d1%8f%d1%82%d0%be%d1%80-%d0%b4%d0%bb%d1%8f-%d0%b2%d0%be%d0%b4%d1%8b/', '{"storage_path": "demo/dentashop/p07-дистиллятор-для-воды.jpg"}'::jsonb, 6 from public.demo_entities where slug = 'dentashop' and not exists (select 1 from public.demo_items x where x.entity_id = demo_entities.id and x.source_url = 'https://dentashop.uz/product/%d0%b4%d0%b8%d1%81%d1%82%d0%b8%d0%bb%d0%bb%d1%8f%d1%82%d0%be%d1%80-%d0%b4%d0%bb%d1%8f-%d0%b2%d0%be%d0%b4%d1%8b/' and x.name = 'Дистиллятор для воды.');
insert into public.demo_items (entity_id, kind, name, price, price_text, currency, image_url, description, source_url, extra, sort_at) select id, 'product', 'Ручная упаковочная машина.', 3250000, '3 250 000 сўм', 'UZS', 'https://dentashop.uz/wp-content/uploads/2020/08/photo_2020-08-24_15-53-21.jpg', 'Упаковочная машина позволяет самостоятельно запечатать пакеты, регулируя их ширину и длину. Для этого используются рулоны разной ширины намотки (она подбирается под размеры инструментов и лотков).', 'https://dentashop.uz/product/%d1%80%d1%83%d1%87%d0%bd%d0%b0%d1%8f-%d1%83%d0%bf%d0%b0%d0%ba%d0%be%d0%b2%d0%be%d1%87%d0%bd%d0%b0%d1%8f-%d0%bc%d0%b0%d1%88%d0%b8%d0%bd%d0%b0-2/', '{"storage_path": "demo/dentashop/p08-ручная-упаковочная-машина-2.jpg"}'::jsonb, 7 from public.demo_entities where slug = 'dentashop' and not exists (select 1 from public.demo_items x where x.entity_id = demo_entities.id and x.source_url = 'https://dentashop.uz/product/%d1%80%d1%83%d1%87%d0%bd%d0%b0%d1%8f-%d1%83%d0%bf%d0%b0%d0%ba%d0%be%d0%b2%d0%be%d1%87%d0%bd%d0%b0%d1%8f-%d0%bc%d0%b0%d1%88%d0%b8%d0%bd%d0%b0-2/' and x.name = 'Ручная упаковочная машина.');
insert into public.demo_items (entity_id, kind, name, price, price_text, currency, image_url, description, source_url, extra, sort_at) select id, 'product', 'Ручная упаковочная машина.', 3900000, '3 900 000 сўм', 'UZS', 'https://dentashop.uz/wp-content/uploads/2020/08/photo_2020-08-24_15-53-27.jpg', 'Упаковочная машина позволяет самостоятельно запечатать пакеты, регулируя их ширину и длину. Для этого используются рулоны разной ширины намотки (она подбирается под размеры инструментов и лотков).', 'https://dentashop.uz/product/%d1%80%d1%83%d1%87%d0%bd%d0%b0%d1%8f-%d1%83%d0%bf%d0%b0%d0%ba%d0%be%d0%b2%d0%be%d1%87%d0%bd%d0%b0%d1%8f-%d0%bc%d0%b0%d1%88%d0%b8%d0%bd%d0%b0/', '{"storage_path": "demo/dentashop/p09-ручная-упаковочная-машина.jpg"}'::jsonb, 8 from public.demo_entities where slug = 'dentashop' and not exists (select 1 from public.demo_items x where x.entity_id = demo_entities.id and x.source_url = 'https://dentashop.uz/product/%d1%80%d1%83%d1%87%d0%bd%d0%b0%d1%8f-%d1%83%d0%bf%d0%b0%d0%ba%d0%be%d0%b2%d0%be%d1%87%d0%bd%d0%b0%d1%8f-%d0%bc%d0%b0%d1%88%d0%b8%d0%bd%d0%b0/' and x.name = 'Ручная упаковочная машина.');
