insert into public.demo_items (entity_id, kind, name, price, price_text, currency, image_url, description, source_url, extra, sort_at) select id, 'product', 'Мини литейный цех  Powerful Cast PC-45', 32500000, '32 500 000 сўм', 'UZS', 'https://dentashop.uz/wp-content/uploads/2020/08/photo_2020-08-11_14-24-06.jpg', 'ЦЕНТРОБЕЖНАЯ ЛИТЕЙНАЯ УСТАНОВКА Powerful Cast PC-45 с комплектом готовый мини литейный цех. В комплекте есть: МУФЕЛЬНАЯ печь, ПЕСКОСТРУЙКА, вакуумный КАСТРЮЛЬ, ЦЕНТРОБЕЖНАЯ ЛИТЕЙНАЯ проспект. Купив установку у нас вы получите бонус стартовый набор и бесплатная мастер класс от специалистами !!!', 'https://dentashop.uz/product/%d0%bc%d0%b8%d0%bd%d0%b8-%d0%bb%d0%b8%d1%82%d0%b5%d0%b9%d0%bd%d1%8b%d0%b9-%d1%86%d0%b5%d1%85-powerful-cast-pc-45/', '{"storage_path": "demo/dentashop/p12-мини-литейный-цех-powerful-cast-pc-45.jpg"}'::jsonb, 11 from public.demo_entities where slug = 'dentashop' and not exists (select 1 from public.demo_items x where x.entity_id = demo_entities.id and x.source_url = 'https://dentashop.uz/product/%d0%bc%d0%b8%d0%bd%d0%b8-%d0%bb%d0%b8%d1%82%d0%b5%d0%b9%d0%bd%d1%8b%d0%b9-%d1%86%d0%b5%d1%85-powerful-cast-pc-45/' and x.name = 'Мини литейный цех  Powerful Cast PC-45');
insert into public.demo_items (entity_id, kind, name, price, price_text, currency, image_url, description, source_url, extra, sort_at) select id, 'product', 'ЦЕНТРОБЕЖНАЯ ЛИТЕЙНАЯ УСТАНОВКА Powerful Cast PC-45', 17550000, '17 550 000 сўм', 'UZS', 'https://dentashop.uz/wp-content/uploads/2020/08/photo_2019-03-04_13-49-25.jpg', 'ЦЕНТРОБЕЖНАЯ ЛИТЕЙНАЯ УСТАНОВКА С кислородно газовой горелкой Powerful Cast PC-45 Установка для литья драгоценных и не драгоценных металлов и сплавов методом высокочастотной индукции. Отличительной особенностью Литейной Установки Powerful Cast PC-45 является надежность и простота в использовании.', 'https://dentashop.uz/product/%d1%86%d0%b5%d0%bd%d1%82%d1%80%d0%be%d0%b1%d0%b5%d0%b6%d0%bd%d0%b0%d1%8f-%d0%bb%d0%b8%d1%82%d0%b5%d0%b9%d0%bd%d0%b0%d1%8f-%d1%83%d1%81%d1%82%d0%b0%d0%bd%d0%be%d0%b2%d0%ba%d0%b0-powerful-cast-pc-45/', '{"storage_path": "demo/dentashop/p13-центробежная-литейная-установка-powerful.jpg"}'::jsonb, 12 from public.demo_entities where slug = 'dentashop' and not exists (select 1 from public.demo_items x where x.entity_id = demo_entities.id and x.source_url = 'https://dentashop.uz/product/%d1%86%d0%b5%d0%bd%d1%82%d1%80%d0%be%d0%b1%d0%b5%d0%b6%d0%bd%d0%b0%d1%8f-%d0%bb%d0%b8%d1%82%d0%b5%d0%b9%d0%bd%d0%b0%d1%8f-%d1%83%d1%81%d1%82%d0%b0%d0%bd%d0%be%d0%b2%d0%ba%d0%b0-powerful-cast-pc-45/' and x.name = 'ЦЕНТРОБЕЖНАЯ ЛИТЕЙНАЯ УСТАНОВКА Powerful Cast PC-45');
